.rheinsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8edf3;
    background:
        linear-gradient(180deg, rgba(13, 20, 33, 0.0) 0%, rgba(8, 13, 22, 0.6) 100%),
        repeating-linear-gradient(0deg, rgba(255,255,255,0.015) 0px, rgba(255,255,255,0.015) 1px, transparent 1px, transparent 28px),
        radial-gradient(circle at 85% 0%, #1b2c40 0%, #0e1726 55%, #0a111d 100%);
    border-radius: 16px;
    border: 1px solid #21344a;
}

.rheinsim-container * {
    box-sizing: border-box;
}

.rheinsim-header {
    text-align: center;
    padding: 26px 22px 22px;
    background: linear-gradient(135deg, #0d1a2c 0%, #15273e 60%, #2a3340 100%);
    color: #f1f6fb;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #28415c;
    border-left: 5px solid #d99a2b;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.50);
}

.rheinsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.2rem;
    font-weight: 800;
    letter-spacing: 0.4px;
    color: #ffffff;
    text-transform: uppercase;
}

.rheinsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f0b94c;
    background: rgba(217, 154, 43, 0.12);
    border: 1px solid rgba(217, 154, 43, 0.35);
    padding: 5px 14px;
    border-radius: 4px;
}

.rheinsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 0.98rem;
    line-height: 1.55;
    color: #b9c8d8;
}

.rheinsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #92a6bd;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.rheinsim-period-counter #currentDay,
.rheinsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f0b94c;
}

.rheinsim-round-name {
    background: rgba(82, 140, 199, 0.16);
    color: #7db4ec;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.80rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-left: 4px;
}

.rheinsim-clock {
    margin-left: auto;
    font-size: 0.80rem;
    font-weight: 700;
    color: #ff8d6b;
    background: rgba(255, 141, 107, 0.12);
    border: 1px solid rgba(255, 141, 107, 0.32);
    padding: 4px 12px;
    border-radius: 4px;
}

.rheinsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.rheinsim-status-card {
    background: linear-gradient(160deg, #15273c 0%, #0f1d2f 100%);
    border-radius: 8px;
    padding: 16px 16px 14px;
    border: 1px solid #25405c;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.40);
    border-top: 4px solid #528cc7;
}

.rheinsim-card-var { border-top-color: #ff8d6b; }
.rheinsim-card-liq { border-top-color: #4fc4a8; }
.rheinsim-card-lev { border-top-color: #f0b94c; }
.rheinsim-card-res { border-top-color: #7db4ec; }

.rheinsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #8298b0;
}

.rheinsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.5px;
}

.rheinsim-card-var .rheinsim-value { color: #ff8d6b; }
.rheinsim-card-liq .rheinsim-value { color: #4fc4a8; }
.rheinsim-card-lev .rheinsim-value { color: #f0b94c; }
.rheinsim-card-res .rheinsim-value { color: #7db4ec; }

.rheinsim-sublabel {
    font-size: 0.75rem;
    color: #768ca5;
    line-height: 1.35;
}

/* State-driven emphasis */
.rheinsim-var-safe .rheinsim-value { color: #4fc4a8; }
.rheinsim-var-safe { border-top-color: #4fc4a8; }
.rheinsim-var-danger .rheinsim-value { color: #ff5c5c; }
.rheinsim-var-danger { border-top-color: #ff4d4d; }

.rheinsim-liq-safe .rheinsim-value { color: #4fc4a8; }
.rheinsim-liq-danger .rheinsim-value { color: #ff5c5c; }
.rheinsim-liq-danger { border-top-color: #ff4d4d; }

.rheinsim-lev-breach .rheinsim-value { color: #ff5c5c; }
.rheinsim-lev-breach { border-top-color: #ff4d4d; }
.rheinsim-lev-safe .rheinsim-value { color: #4fc4a8; }

.rheinsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0c1726;
    border: 1px solid #25405c;
    border-left: 4px solid #f0b94c;
    color: #cdddee;
    padding: 10px 18px;
    border-radius: 6px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.rheinsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0b94c;
    font-variant-numeric: tabular-nums;
}

.rheinsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #15273c 0%, #0f1d2f 100%);
    border-left: 5px solid #7db4ec;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.rheinsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.rheinsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.rheinsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #bccbdb;
}

.rheinsim-briefing-text strong { color: #f0b94c; }
.rheinsim-briefing-text em { color: #ff8d6b; font-style: italic; }

.rheinsim-controls {
    background: linear-gradient(160deg, #11203250 0%, #0c182850 100%), #0e1a2a;
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #25405c;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.rheinsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.10rem;
    font-weight: 800;
    color: #ffffff;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    border-bottom: 2px solid #25405c;
    padding-bottom: 8px;
}

.rheinsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cddcec;
    margin: 14px 0 6px;
}

.rheinsim-container select,
.rheinsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2e4a68;
    border-radius: 6px;
    font-size: 0.92rem;
    background-color: #0b1727;
    color: #eaf2fb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.rheinsim-container select:focus,
.rheinsim-container input[type="number"]:focus {
    outline: none;
    border-color: #f0b94c;
    box-shadow: 0 0 0 3px rgba(240, 185, 76, 0.18);
}

.rheinsim-container select option {
    background-color: #0b1727;
    color: #eaf2fb;
}

.rheinsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f0b94c;
}

.rheinsim-range-readout,
.rheinsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #92a6bd;
    margin-top: 4px;
}

.rheinsim-range-readout span:last-child,
.rheinsim-alloc-readout span:nth-child(2) {
    color: #f0b94c;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.rheinsim-hint {
    font-size: 0.8rem;
    color: #768ca5;
    margin-top: 4px;
    line-height: 1.4;
}

.rheinsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.rheinsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0b1727;
    border: 1px solid #2a4564;
    border-radius: 6px;
    padding: 8px 12px;
}

.rheinsim-alloc-name {
    flex: 1;
    font-size: 0.87rem;
    font-weight: 600;
    color: #cddcec;
}

.rheinsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.rheinsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.rheinsim-container .btn-primary {
    background: linear-gradient(135deg, #b97e1c 0%, #f0b94c 100%);
    border: none;
    color: #221603;
    padding: 11px 28px;
    border-radius: 6px;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    box-shadow: 0 8px 18px rgba(185, 126, 28, 0.40);
}

.rheinsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.rheinsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2e4a68;
    color: #92a6bd;
    background: transparent;
}

.rheinsim-coach {
    background: linear-gradient(160deg, #0c1726 0%, #14202c 100%);
    color: #d6e3f0;
    border: 1px solid #2a3f4a;
    border-left: 5px solid #ff8d6b;
    border-radius: 8px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.rheinsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ff8d6b;
    margin-bottom: 8px;
}

.rheinsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.rheinsim-coach-body strong { color: #f0b94c; }
.rheinsim-coach-body em { color: #ff8d6b; font-style: italic; }

.rheinsim-history,
.rheinsim-chart {
    background: linear-gradient(160deg, #11203250 0%, #0c182850 100%), #0e1a2a;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #25405c;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.rheinsim-history h3,
.rheinsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.06rem;
    font-weight: 800;
    color: #ffffff;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.rheinsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.87rem;
    color: #cddcec;
    border-collapse: collapse;
}

.rheinsim-container table#usfHistoryTable th {
    background: #0b1727;
    color: #f0b94c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.70rem;
    letter-spacing: 0.5px;
    padding: 8px 10px;
    border-bottom: 2px solid #2a4564;
    text-align: left;
}

.rheinsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1c2c40;
    color: #bccbdb;
    font-variant-numeric: tabular-nums;
}

.rheinsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0c1828;
}

.rheinsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .rheinsim-container {
        padding: 14px;
    }
    .rheinsim-header h1 {
        font-size: 1.6rem;
    }
    .rheinsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .rheinsim-value {
        font-size: 1.9rem;
    }
    .rheinsim-clock {
        margin-left: 0;
    }
    .rheinsim-period-counter {
        font-size: 0.86rem;
    }
    .rheinsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .rheinsim-alloc-row {
        flex-wrap: wrap;
    }
    .rheinsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .rheinsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained) */
.rheinsim-cm { background:#f4f7fa; color:#25405c; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(37,64,92,0.2); }
.rheinsim-cm-head { text-align:center; border-bottom:1px solid #d2dde7; padding-bottom:14px; margin-bottom:16px; }
.rheinsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#3f7fa8; font-weight:700; }
.rheinsim-cm-scorewrap { margin:8px 0 2px; }
.rheinsim-cm-score { font-size:52px; font-weight:800; color:#25405c; line-height:1; }
.rheinsim-cm-score-max { font-size:20px; color:#8397a8; font-weight:600; }
.rheinsim-cm-grade { font-size:19px; font-weight:700; color:#25405c; margin-top:4px; }
.rheinsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.rheinsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.rheinsim-cm-met { background:#c9ece1; color:#12715a; }
.rheinsim-cm-fail { background:#f7ddd4; color:#a4442c; }
.rheinsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.rheinsim-cm-metric { background:#e6edf3; border-radius:10px; padding:12px 16px; min-width:96px; text-align:center; }
.rheinsim-cm-metric-val { font-size:20px; font-weight:800; color:#25405c; }
.rheinsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#3f7fa8; margin-top:3px; }
.rheinsim-cm-insights { background:#e6edf3; border-radius:10px; padding:14px 18px; }
.rheinsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#3f7fa8; font-weight:700; margin-bottom:8px; }
.rheinsim-cm-insights ul { margin:0; padding-left:18px; }
.rheinsim-cm-insights li { font-size:14px; line-height:1.5; color:#2e4a63; margin-bottom:7px; }

