(function() {
    'use strict';

    class RheinwerkAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Risk on the Balance Sheet`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Rheinwerk Komponenten AG).
            this.EBITDA = 59.4;              // EUR 59.4M EBITDA line
            this.BASELINE_VAR = 24;         // EUR 24M baseline earnings VaR (correlated)
            this.VAR_TOLERANCE = 15;        // EUR 15M board VaR tolerance (R2 target)
            this.LIQ_FLOOR = 20;            // EUR 20M liquidity-headroom floor (R2 constraint)
            this.RISK_BUDGET = 12;          // EUR 12M risk budget (R2)
            this.COVENANT = 3.75;           // 3.75x leverage covenant ceiling
            this.SYND_LOAN = 180;           // EUR 180M syndicated loan
            this.MARGIN_STEP_COST = 3.6;    // ~EUR 3.6M/yr cost of +200 bps on EUR 180M

            // Concept truths.
            this.TRUE_CORR = `correlated`;
            this.TRUE_TOP = `liquidity`;
            this.TRUE_PRIORITY = `balanced`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    var: 24,                 // EUR M earnings VaR (12m, 95%) — lower better
                    liq: 11,                 // EUR M liquidity headroom — higher better
                    lev: 3.50,               // pro-forma leverage (x EBITDA) — lower better
                    res: 30,                 // financial-resilience score 0–100 — higher better
                    budgetUsed: 0,           // EUR M of risk budget committed
                    covenantBreached: false, // pro-forma leverage above the ceiling at any point
                    optionalitySold: false,  // sold the EV-ready plant
                    correlationSeen: false,  // recognised the correlated VaR
                    hedgeAccuracy: 0.80,     // R1 correlation handling → R2 hedge effectiveness
                    varHistory: [24],
                    liqHistory: [11],
                    levHistory: [3.50],
                    resHistory: [30],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    corr: `independent`,
                    topRisk: `commodity`,
                    register: 50,
                    collar: 3,
                    fx: 3,
                    reserve: 3,
                    factor: 2,
                    insurance: 1,
                    priority: `var`,
                    path: `defend`,
                    sequence: `upfront`,
                    structural: `2030`,
                    waiver: `accept`,
                    bridge: `growth`,
                    margin: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const co = document.getElementById(`corrInput`);
                const tr = document.getElementById(`topRiskInput`);
                const rg = document.getElementById(`registerInput`);
                if (co) decisions.corr = co.value;
                if (tr) decisions.topRisk = tr.value;
                if (rg) decisions.register = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.register) || decisions.register < 0 || decisions.register > 100) {
                    warn(`warn_register_range`); return false;
                }
            } else if (round === 2) {
                const cl = document.getElementById(`collarInput`);
                const fx = document.getElementById(`fxInput`);
                const rv = document.getElementById(`reserveInput`);
                const ft = document.getElementById(`factorInput`);
                const ins = document.getElementById(`insuranceInput`);
                const pr = document.getElementById(`priorityInput`);
                if (cl) decisions.collar = parseFloat(cl.value);
                if (fx) decisions.fx = parseFloat(fx.value);
                if (rv) decisions.reserve = parseFloat(rv.value);
                if (ft) decisions.factor = parseFloat(ft.value);
                if (ins) decisions.insurance = parseFloat(ins.value);
                if (pr) decisions.priority = pr.value;
                const parts = [decisions.collar, decisions.fx, decisions.reserve, decisions.factor, decisions.insurance];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.collar + decisions.fx + decisions.reserve + decisions.factor + decisions.insurance) * 10) / 10;
                if (Math.abs(total - this.RISK_BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const pa = document.getElementById(`pathInput`);
                const sq = document.getElementById(`sequenceInput`);
                const st = document.getElementById(`structuralInput`);
                if (pa) decisions.path = pa.value;
                if (sq) decisions.sequence = sq.value;
                if (st) decisions.structural = st.value;
                if (decisions.path === `defend` && decisions.sequence === `na`) {
                    warn(`warn_sequence_defend`); return false;
                }
            } else if (round === 4) {
                const wv = document.getElementById(`waiverInput`);
                const br = document.getElementById(`bridgeInput`);
                const mg = document.getElementById(`marginInput`);
                if (wv) decisions.waiver = wv.value;
                if (br) decisions.bridge = br.value;
                if (mg) decisions.margin = parseInt(mg.value, 10);
                if (!Number.isFinite(decisions.margin) || decisions.margin < 0 || decisions.margin > 100) {
                    warn(`warn_margin_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let varDelta = 0, liqDelta = 0, levDelta = 0, resDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the risk. Correlation is the central ERM insight (Common Error 1).
                switch (d.corr) {
                    case `correlated`:
                        // Recognise that correlated risks add far more VaR than the sum.
                        // The team now sizes mitigation against the TRUE exposure, so the
                        // Round-2 hedges land at full effectiveness (hedgeAccuracy = 1.0)
                        // and resilience rises. The live VaR is NOT inflated — knowing the
                        // real number is what lets the budget actually buy it down.
                        ds.hedgeAccuracy = 1.0; resDelta += 14; ds.correlationSeen = true; coachKey = `coach_r1_correlated`;
                        break;
                    case `partial`:
                        // A qualitative flag without re-estimating the number: hedges are
                        // sized against the understated baseline, so they under-deliver.
                        ds.hedgeAccuracy = 0.80; resDelta += 4; coachKey = `coach_r1_partial`;
                        break;
                    case `independent`:
                        // Summing standalone exposures badly under-states VaR; the budget is
                        // mis-sized and the unmeasured tail keeps leaking into earnings VaR.
                        ds.hedgeAccuracy = 0.60; resDelta -= 8; coachKey = `coach_r1_independent`;
                        break;
                }

                // Rank the most dangerous exposure (survival before profit — Common Error 2/6).
                switch (d.topRisk) {
                    case `liquidity`: resDelta += 8; liqDelta += 1; if (d.corr === `correlated`) coachKey = `coach_r1_sharp`; break;
                    case `commodity`: resDelta += 1; break;
                    case `structural`: resDelta -= 6; coachKey = `coach_r1_structural`; break;
                }

                // Rigour of the enterprise risk map.
                if (d.register >= 65) { resDelta += 6; }
                else if (d.register <= 30) { resDelta -= 6; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.corr === `correlated` && d.topRisk === `liquidity`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the EUR 12M risk budget (Common Error 2: hedge P&L, ignore wall).
                const collar = d.collar, fx = d.fx, reserve = d.reserve, factor = d.factor, insurance = d.insurance;
                spend = collar + fx + reserve + factor + insurance;

                // VaR reduction per instrument (EUR M of VaR removed per EUR M spent),
                // scaled by how accurately the risk was sized in Round 1. A correlation-
                // aware register (acc 1.0) buys down the true exposure; an independent one
                // (acc 0.6) mis-sizes the hedges and leaves residual VaR in the book.
                const acc = (typeof ds.hedgeAccuracy === `number`) ? ds.hedgeAccuracy : 0.80;
                varDelta -= collar * 1.6 * acc;  // commodity collar — strong VaR cut, residual upside risk
                varDelta -= fx * 1.5 * acc;      // layered FX hedge — strong VaR cut
                varDelta -= insurance * 1.8 * acc; // credit insurance — transfers counterparty tail risk
                varDelta -= factor * 0.5 * acc;  // factoring trims a little credit VaR

                // Liquidity effect per instrument.
                liqDelta += reserve * 1.5;       // precautionary reserve / standby line — pure headroom
                liqDelta += factor * 4.0;        // factoring releases the trapped ~EUR 22M (big headroom)
                liqDelta -= (collar + fx) * 0.4; // hedge margin/premium ties up a little cash

                resDelta += insurance * 2 + reserve * 1.2 + factor * 0.8;

                // The classic error: spend it all on hedging, leave no liquidity reserve.
                const hedgeSpend = collar + fx;
                const liquiditySpend = reserve + factor;
                if (hedgeSpend >= 9 && liquiditySpend <= 1.5) {
                    resDelta -= 8; coachKey = `coach_r2_hedgeonly`;
                } else if (liquiditySpend >= 9 && hedgeSpend <= 1.5) {
                    resDelta -= 4; coachKey = `coach_r2_liquidityonly`;
                }

                // Priority framing — survival and earnings risk are different objectives.
                switch (d.priority) {
                    case `balanced`: resDelta += 6; if (coachKey === `coach_default`) coachKey = `coach_r2_balanced`; break;
                    case `var`: resDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_varfirst`; break;
                    case `liquidity`: varDelta += 2; if (coachKey === `coach_default`) coachKey = `coach_r2_liqfirst`; break;
                }

                // Apply provisionally to test whether targets are hit.
                const projVar = ds.var + varDelta;
                const projLiq = ds.liq + liqDelta;
                const hitVar = projVar <= this.VAR_TOLERANCE;
                const hitLiq = projLiq >= this.LIQ_FLOOR;
                if (hitVar && hitLiq) { resDelta += 10; coachKey = `coach_r2_bothtargets`; }
                else if (hitVar && !hitLiq) { resDelta -= 6; coachKey = `coach_r2_walligonore`; }
                else if (!hitVar && hitLiq) { resDelta -= 2; }

                summaryKey = (hitVar && hitLiq) ? `sum_r2_good` :
                             (!hitLiq && hitVar ? `sum_r2_wall` : `sum_r2_weak`);
            } else if (round === 3) {
                // Choose the restructuring path under the liquidity constraint.
                switch (d.path) {
                    case `defend`:
                        // EV conversion: highest growth, highest burn, covenant pressure.
                        if (d.sequence === `upfront`) {
                            // EUR 25M capex pushes leverage to ~3.9x — breach (Common Error 3).
                            levDelta += 0.40; liqDelta -= 8; resDelta += 6; ds.covenantBreached = true;
                            coachKey = `coach_r3_defendbreach`;
                        } else { // phased
                            // Sequenced so pro-forma leverage stays under the ceiling.
                            levDelta += 0.12; liqDelta -= 4; resDelta += 14;
                            coachKey = `coach_r3_defendphased`;
                        }
                        break;
                    case `reshape`:
                        // Close Hungary: EUR 8M one-off cash cost, +EUR 3M EBITDA recovery.
                        liqDelta -= 2; levDelta -= 0.10; resDelta += 9;
                        coachKey = `coach_r3_reshape`;
                        break;
                    case `deleverage`:
                        // Sale-and-leaseback raises EUR 55M, leverage to ~2.6x, surrenders optionality.
                        levDelta -= 0.90; liqDelta += 14; resDelta -= 6; ds.optionalitySold = true;
                        coachKey = `coach_r3_deleverage`;
                        break;
                }

                // Structural combustion risk: a now problem, not a 2030 problem (Common Error 6).
                switch (d.structural) {
                    case `now`: resDelta += 8; if (d.path === `defend` && d.sequence === `phased`) coachKey = `coach_r3_sharp`; break;
                    case `2030`: resDelta -= 6; varDelta += 2; if (coachKey === `coach_default`) coachKey = `coach_r3_structuralwait`; break;
                }

                summaryKey = (d.path === `reshape` && d.structural === `now`) ? `sum_r3_reshape` :
                             (d.path === `defend` && d.sequence === `phased` && d.structural === `now`) ? `sum_r3_defend` :
                             (ds.covenantBreached ? `sum_r3_breach` :
                             (d.path === `deleverage` ? `sum_r3_deleverage` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the plan to the syndicate (Common Error 5: accept terms passively).
                const m = d.margin / 100;
                switch (d.waiver) {
                    case `negotiate`:
                        // Trade a smaller step-up for maturity + a covenant holiday.
                        resDelta += 12; liqDelta += 2;
                        // Margin pushback recovers part of the EUR 3.6M/yr step-up cost.
                        liqDelta += m * 2;
                        coachKey = `coach_r4_negotiate`;
                        break;
                    case `accept`:
                        // +200 bps on EUR 180M — EUR 3.6M/yr, more than the Hungary EBITDA.
                        liqDelta -= 3; resDelta -= 6;
                        coachKey = `coach_r4_accept`;
                        break;
                    case `reject`:
                        // Refuse the repricing — only safe if leverage is already inside the ceiling.
                        if (ds.lev <= this.COVENANT && !ds.covenantBreached) { resDelta += 6; coachKey = `coach_r4_rejectsafe`; }
                        else { resDelta -= 10; ds.covenantBreached = true; coachKey = `coach_r4_rejectrisky`; }
                        break;
                }

                // What anchors the credit-committee presentation.
                switch (d.bridge) {
                    case `bridge`: resDelta += 10; coachKey = (d.waiver === `negotiate`) ? `coach_r4_defend` : coachKey; break;
                    case `growth`: resDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r4_growth`; break;
                    case `apology`: resDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r4_apology`; break;
                }

                if (d.margin >= 60 && d.waiver !== `accept`) { liqDelta += 1; }
                else if (d.margin <= 25 && d.waiver === `negotiate`) { resDelta -= 3; coachKey = `coach_r4_softpush`; }

                summaryKey = (d.waiver === `negotiate` && d.bridge === `bridge`) ? `sum_r4_good` :
                             (d.waiver === `accept` ? `sum_r4_passive` : `sum_r4_weak`);
            }

            // Resource accounting: the EUR 12M risk budget is metered in R2 only.
            ds.budgetUsed = Math.min(this.RISK_BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas with clamps. VaR floor 0; leverage floor 1.0; resilience 0–100.
            ds.var = Math.max(0, Math.round((ds.var + varDelta) * 10) / 10);
            ds.liq = Math.round((ds.liq + liqDelta) * 10) / 10;
            ds.lev = Math.max(1.0, Math.round((ds.lev + levDelta) * 100) / 100);
            ds.res = Math.max(0, Math.min(100, Math.round(ds.res + resDelta)));

            if (ds.lev > this.COVENANT) ds.covenantBreached = true;

            ds.varHistory.push(ds.var);
            ds.liqHistory.push(ds.liq);
            ds.levHistory.push(ds.lev);
            ds.resHistory.push(ds.res);

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                var: ds.var,
                varDelta: Math.round(varDelta * 10) / 10,
                liq: ds.liq,
                liqDelta: Math.round(liqDelta * 10) / 10,
                lev: ds.lev,
                levDelta: Math.round(levDelta * 100) / 100,
                res: ds.res,
                resDelta: Math.round(resDelta),
                budgetUsed: ds.budgetUsed,
                covenantBreached: ds.covenantBreached,
                optionalitySold: ds.optionalitySold,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR: English "€24.0M" (symbol before), Spanish "24,0 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

        _fmtLev(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Number(v).toFixed(2);
            return (lang === `es` ? n.replace(`.`, `,`) : n) + `x`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`varDisplay`, `domainState.var`, (v) => {
                const card = document.querySelector(`.rheinsim-card-var`);
                if (card) {
                    card.classList.toggle(`rheinsim-var-safe`, Number(v) <= self.VAR_TOLERANCE);
                    card.classList.toggle(`rheinsim-var-danger`, Number(v) >= 22);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`liqDisplay`, `domainState.liq`, (v) => {
                const card = document.querySelector(`.rheinsim-card-liq`);
                if (card) {
                    card.classList.toggle(`rheinsim-liq-safe`, Number(v) >= self.LIQ_FLOOR);
                    card.classList.toggle(`rheinsim-liq-danger`, Number(v) < 12);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`levDisplay`, `domainState.lev`, (v) => {
                const card = document.querySelector(`.rheinsim-card-lev`);
                if (card) {
                    card.classList.toggle(`rheinsim-lev-breach`, Number(v) > self.COVENANT);
                    card.classList.toggle(`rheinsim-lev-safe`, Number(v) <= 3.0);
                }
                return self._fmtLev(Number(v));
            });
            uiManager.bind(`resDisplay`, `domainState.res`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.RISK_BUDGET);
            });

            // Register-rigour slider readout.
            const rg = document.getElementById(`registerInput`);
            const rgReadout = document.getElementById(`registerReadout`);
            if (rg && rgReadout) {
                rgReadout.textContent = rg.value;
                rg.addEventListener(`input`, function() { rgReadout.textContent = rg.value; });
            }

            // Risk-budget live total (must hit EUR 12M).
            const allocIds = [`collarInput`, `fxInput`, `reserveInput`, `factorInput`, `insuranceInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.rheinsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.RISK_BUDGET) > 0.001) ? `#ff6b5e` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

