        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.varHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                rheinChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.varHistory },
                        { data: ds.liqHistory },
                        { data: ds.levHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const earnVar = ds.var;
            const liq = ds.liq;
            const lev = ds.lev;
            const res = Math.round(ds.res);
            const varScore = Math.max(0, Math.min(100, (24 - earnVar) / 24 * 100));
            const liqScore = Math.max(0, Math.min(100, liq / 30 * 100));
            const levScore = Math.max(0, Math.min(100, (4.2 - lev) / (4.2 - 2.6) * 100));
            return Math.round(varScore * 0.22 + liqScore * 0.24 + levScore * 0.20 + res * 0.34);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const earnVar = ds.var;
            const liq = ds.liq;
            const lev = ds.lev;
            const res = Math.round(ds.res);

            const varOk = earnVar <= this.VAR_TOLERANCE;
            const liqOk = liq >= this.LIQ_FLOOR;
            const covenantOk = lev <= this.COVENANT && !ds.covenantBreached;

            // Composite: low VaR, ample liquidity, covenant compliance, and resilience.
            // VaR scored vs 24→0 scale; liquidity vs a 30 target; leverage vs the 3.75 ceiling.
            const varScore = Math.max(0, Math.min(100, (24 - earnVar) / 24 * 100));
            const liqScore = Math.max(0, Math.min(100, liq / 30 * 100));
            const levScore = Math.max(0, Math.min(100, (4.2 - lev) / (4.2 - 2.6) * 100));
            const composite = this._composite(ds);

            let performanceKey = `grade_rejected`;
            if (varOk && liqOk && covenantOk && res >= 70 && composite >= 75) performanceKey = `grade_resilient`;
            else if (liqOk && covenantOk && composite >= 60) performanceKey = `grade_held`;
            else if (ds.covenantBreached) performanceKey = `grade_breached`;
            else if (!liqOk) performanceKey = `grade_wall`;
            else if (composite >= 50) performanceKey = `grade_partial`;
            const performance = window.mySimulation.t(performanceKey);
            const met = varOk && liqOk && covenantOk && res >= 70 && composite >= 75;

            const insights = [];
            if (varOk && liqOk && covenantOk && res >= 70) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (ds.covenantBreached) insights.push(window.mySimulation.t(`insight_breach`));
            else if (!liqOk) insights.push(window.mySimulation.t(`insight_wall`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (!ds.correlationSeen) insights.push(window.mySimulation.t(`insight_nocorrelation`));
            if (ds.optionalitySold) insights.push(window.mySimulation.t(`insight_optionality`));
            if (varOk && !liqOk) insights.push(window.mySimulation.t(`insight_hedgedwall`));
            if (covenantOk && res >= 70) insights.push(window.mySimulation.t(`insight_negotiated`));
            if (liq < 12) insights.push(window.mySimulation.t(`insight_liqlow`));

            return {
                var: earnVar,
                liq: liq,
                lev: lev,
                res: res,
                varOk: varOk,
                liqOk: liqOk,
                covenantOk: covenantOk,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="rheinsim-cm-badge ` + (s.met ? `rheinsim-cm-met` : `rheinsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.covenantOk === false) badges.push(`<span class="rheinsim-cm-badge rheinsim-cm-fail">` + t(`cm_fail_covenant`) + `</span>`);
            if (s.liqOk === false) badges.push(`<span class="rheinsim-cm-badge rheinsim-cm-fail">` + t(`cm_fail_liq`) + `</span>`);
            if (s.varOk === false) badges.push(`<span class="rheinsim-cm-badge rheinsim-cm-fail">` + t(`cm_fail_var`) + `</span>`);
            const kpi = (label, val) => `<div class="rheinsim-cm-metric"><div class="rheinsim-cm-metric-val">` + val + `</div><div class="rheinsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_var`), (s.var != null ? this._fmtMoney(Number(s.var)) : `-`))
                + kpi(t(`cm_liq`), (s.liq != null ? this._fmtMoney(Number(s.liq)) : `-`))
                + kpi(t(`cm_lev`), (s.lev != null ? this._fmtLev(Number(s.lev)) : `-`))
                + kpi(t(`cm_res`), (s.res != null ? Math.round(s.res) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="rheinsim-cm">`
                + `<div class="rheinsim-cm-head"><div class="rheinsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="rheinsim-cm-scorewrap"><span class="rheinsim-cm-score">` + score + `</span><span class="rheinsim-cm-score-max">/100</span></div>`
                + `<div class="rheinsim-cm-grade">` + grade + `</div>`
                + `<div class="rheinsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="rheinsim-cm-metrics">` + kpis + `</div>`
                + `<div class="rheinsim-cm-insights"><div class="rheinsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.covenantBreached) return window.mySimulation.t(`hint_breach`);
            if (ds.liq < this.LIQ_FLOOR && state.currentPeriod >= 2) return window.mySimulation.t(`hint_wall`);
            if (ds.var > this.VAR_TOLERANCE && state.currentPeriod >= 2) return window.mySimulation.t(`hint_var`);
            if (ds.optionalitySold) return window.mySimulation.t(`hint_optionality`);
            if (!ds.correlationSeen && state.currentPeriod >= 1) return window.mySimulation.t(`hint_correlation`);
            if (ds.var <= this.VAR_TOLERANCE && ds.liq >= this.LIQ_FLOOR && ds.lev <= this.COVENANT) return window.mySimulation.t(`hint_strong`);
            return null;
        }

